export const GLOSSARY_SHARD = Object.freeze({"bitcoin":{"slug":"bitcoin","cat":"basics","en":"Bitcoin (BTC)","contentLocale":"zh-Hans","term":"比特币（Bitcoin，BTC）","aka":["BTC","Bitcoin","大饼"],"short":"比特币是 2009 年上线的第一个去中心化加密货币，总量上限 2100 万枚，通过工作量证明挖矿维护网络，代号 BTC。","body":[["比特币由化名“中本聪”的作者提出，没有公司或央行发行。新的比特币通过",["挖矿","mining"],"产生：矿工用",["算力","hash-rate"],"竞争打包区块，赢得的一方获得区块奖励和交易手续费。规则写在协议里，总量最多 2100 万枚，每约四年区块奖励减半一次，2024 年 4 月减半后降至每块 3.125 BTC。"],["比特币可以拆分得很细，1 BTC 等于 1 亿聪（sats）。币圈常把 BTC 叫“大饼”，它通常是",["市值","market-capitalization"],"最大的",["加密货币","cryptocurrency"],"，很多",["山寨币","altcoin"],"的走势会受它影响。2024 年 1 月美国现货比特币 ETF 开始交易，让传统投资者多了一条间接持有的渠道。"],["比特币价格波动很大，它的价值来自市场共识而非任何资产担保。你可以在",["交易所","centralized-exchange"],"现货买入，也可以提到自己的钱包自行保管；比特币链上转账手续费按交易数据大小和拥堵程度浮动。"]],"example":"假设 BTC 价格为 60,000 USDT，你想投入 300 USDT。300 ÷ 60,000 = 0.005 BTC，也就是 500,000 聪。如果之后价格涨到 66,000 USDT，你的持仓价值变为 330 USDT，涨幅 10%；若跌到 54,000 USDT，则只剩 270 USDT。你并不需要买满一整枚。","mistakes":["以为必须买一整枚比特币，其实可以按金额买入零头。","把比特币转到不支持 BTC 网络的地址，或在提币时选错网络。","看到减半就认定价格一定上涨，历史表现不代表未来。"],"faq":[{"q":"比特币为什么叫“大饼”？","a":"这是国内币圈的俗称，因为比特币的图标像一块圆饼，以太坊则常被叫作“姨太”或“二饼”。"},{"q":"比特币挖完了会怎样？","a":"按当前规则，最后一批比特币预计要到 2140 年前后才挖完。之后矿工只能靠交易手续费获得收入。"},{"q":"比特币总量真的只有 2100 万枚吗？","a":"是的，上限写在协议规则中，改变它需要全网绝大多数参与者同意，实际上几乎不可能。"}],"title":"什么是比特币（BTC）？比特币的含义与基本原理","description":"比特币是什么、2100 万枚上限和减半机制如何运作、1 BTC 等于多少聪，以及新手如何按金额买入一小部分比特币。","related":[["satoshi","聪（Satoshi，sats）","聪是比特币的最小单位，1 BTC 等于 1 亿聪，以比特币创始人中本聪命名，英文常写作 sats。"],["bitcoin-halving","比特币减半（Bitcoin Halving）","比特币减半是指每产出 21 万个区块（约四年）矿工的区块奖励自动减少一半的规则，2024 年 4 月减半后奖励降至 3.125 BTC。"],["proof-of-work","工作量证明（PoW）","工作量证明（PoW）是一种共识机制，矿工通过大量计算竞争求解哈希难题，最先找到答案的人获得出块权和奖励，比特币采用这种机制。"],["mining","挖矿（Crypto Mining）","挖矿是在工作量证明区块链上用计算设备竞争打包区块、维护网络安全并获得新币奖励和手续费的过程。"],["spot-bitcoin-etf","比特币现货ETF（Spot bitcoin ETF）","比特币现货ETF是在证券交易所上市、由基金直接持有真实比特币的交易所交易基金，投资者通过证券账户买卖份额，就能获得跟踪比特币价格的敞口。"]],"lesson":{"id":"E01","slug":"can-i-buy-part-of-a-bitcoin","ep":1,"title":"一枚比特币太贵，我就不能买吗？"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":true},"proof-of-work":{"slug":"proof-of-work","cat":"basics","en":"Proof of work (PoW)","contentLocale":"zh-Hans","term":"工作量证明（PoW）","aka":["PoW","Proof of Work"],"short":"工作量证明（PoW）是一种共识机制，矿工通过大量计算竞争求解哈希难题，最先找到答案的人获得出块权和奖励，比特币采用这种机制。","body":[["在 PoW 网络里，矿工不断尝试不同的随机数，计算区块数据的",["哈希值","transaction-hash"],"，直到结果低于网络规定的目标值。这个过程没有捷径，只能靠反复计算，所以谁的",["算力","hash-rate"],"占比越高，平均出块的概率就越大。"],["PoW 的安全性来自成本：要篡改历史记录，攻击者需要掌握超过全网一半的算力，并承担巨额的电费和设备成本。",["比特币","bitcoin"],"会根据出块速度大约每两周（每 2016 个区块）调整一次难度，让平均出块时间保持在 10 分钟左右。"],["PoW 的主要争议是能耗高。",["以太坊","ethereum"],"在 2022 年 9 月改用",["权益证明（PoS）","proof-of-stake"],"，而比特币、莱特币、狗狗币仍使用 PoW。对普通用户来说，PoW 链的转账通常需要等待若干",["区块确认","block-confirmations"],"后才被交易所视为到账。"]],"example":"假设全网算力为 600 EH/s，你的矿机算力为 200 TH/s。你的算力占比 = 200 TH/s ÷ 600,000,000 TH/s，约为三百万分之一。一天约产出 144 个区块，你平均要等很多年才能单独挖到一个区块，所以个人矿工通常加入矿池，按算力贡献比例分配收益。","mistakes":["以为挖矿是在“解数学题”从而有智力门槛，其实是纯粹的暴力计算。","把 PoW 和 PoS 混为一谈，以为以太坊现在仍可以挖矿。","只算矿机价格不算电费和难度上升，高估挖矿回报。"],"faq":[{"q":"PoW 和 PoS 有什么区别？","a":"PoW 靠算力竞争出块，成本是电力和矿机；PoS 靠质押代币获得出块资格，成本是锁定的资金和被罚没的风险。"},{"q":"什么是 51% 攻击？","a":"指攻击者控制超过全网一半算力后，可以重组近期区块、造成双花。在大型 PoW 网络上发动这种攻击的成本极高。"}],"title":"什么是工作量证明（PoW）？含义与原理","description":"工作量证明（PoW）是什么？讲清矿工如何竞争出块、难度调整如何运作、PoW 为何安全又耗能，以及和 PoS 的区别。","related":[["mining","挖矿（Crypto Mining）","挖矿是在工作量证明区块链上用计算设备竞争打包区块、维护网络安全并获得新币奖励和手续费的过程。"],["hash-rate","算力（Hash rate）","算力是矿机或整个工作量证明网络每秒能完成的哈希计算次数，常用TH/s、EH/s表示，全网算力越高，攻击网络所需的成本通常越高。"],["proof-of-stake","权益证明（PoS）","权益证明（PoS）是一种共识机制，验证者通过质押代币获得出块和验证资格，作恶会被罚没质押，以太坊自 2022 年起采用。"],["blockchain","区块链（Blockchain）","区块链是一种由众多节点共同维护、按时间顺序把交易打包成区块并用密码学串联起来的公开账本，写入后极难篡改。"],["bitcoin-halving","比特币减半（Bitcoin Halving）","比特币减半是指每产出 21 万个区块（约四年）矿工的区块奖励自动减少一半的规则，2024 年 4 月减半后奖励降至 3.125 BTC。"]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"token-unlock":{"slug":"token-unlock","cat":"basics","en":"Token unlock","contentLocale":"zh-Hans","term":"代币解锁（Token Unlock）","aka":["Token unlock","解锁","解禁"],"short":"代币解锁是指原本锁仓、不能交易的代币按预定时间表释放进入流通，常见于团队、投资人和生态基金的份额。","body":["为了避免团队和投资人一上线就抛售，项目通常会设置锁仓期（Cliff）和释放期（Vesting）。锁仓期内一枚都不能卖，之后可能一次性解锁一部分，再按月或按天线性释放。",["解锁会增加",["流通量","circulating-supply"],"。如果解锁对象是成本极低的早期投资人，他们有较强的卖出动机，市场往往会提前关注大额解锁日期。不过解锁并不等于一定被卖出，有的会继续",["质押","staking"],"或",["长期持有","hodl"],"。"],["评估解锁影响时，可以看解锁量占当前流通量的比例、日均",["成交量","trading-volume"],"能否承接，以及接收方是谁。各数据平台会整理解锁日历，但具体以项目官方披露和链上转账为准。"]],"example":["假设某代币当前流通 2 亿枚，价格 1.2 ",["USDT","usdt"],"，日均成交额约 3,000 万 USDT。下周投资人份额一次性解锁 4,000 万枚，相当于流通量增加 20%，价值约 4,800 万 USDT，是日均成交额的 1.6 倍。如果其中一半被卖出，就需要约 2,400 万 USDT 的新买盘来承接。"],"mistakes":["不知道解锁日历，在大额解锁前重仓买入。","认为解锁当天一定暴跌，实际上价格可能早已提前反映。","只看解锁的绝对数量，不和流通量及成交量比较。"],"faq":[{"q":"代币解锁一定会导致价格下跌吗？","a":"不一定。影响取决于解锁规模、接收方是否卖出以及市场需求，有时市场已提前消化。"},{"q":"Cliff 和 Vesting 是什么意思？","a":"Cliff 是锁仓期，期间完全不能动；Vesting 是之后的分期释放安排，比如按月线性解锁。"}],"title":"什么是代币解锁？Token Unlock 的含义与影响","description":"代币解锁是什么意思？讲清锁仓期和线性释放、解锁如何增加流通量，以及怎样用流通量和成交量评估大额解锁的影响。","related":[["tokenomics","代币经济学（Tokenomics）","代币经济学是指一个代币的供应量、分配比例、解锁节奏、用途和销毁机制等设计，决定了代币未来的供需结构。"],["circulating-supply","流通量（Circulating Supply）","流通量是指当前已在市场上自由流通、可以被交易的代币数量，不包括仍处于锁仓或尚未发行的部分。"],["fully-diluted-valuation","完全稀释估值（FDV）","完全稀释估值（FDV）是用当前价格乘以代币最大供应量（或总供应量）算出的估值，表示所有代币都流通后的理论市值。"],["airdrop","空投（Airdrop）","空投是项目方免费向符合条件的钱包地址或用户发放代币的方式，常用于奖励早期用户、分散持币和推广项目。"]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"limit-order":{"slug":"limit-order","cat":"trading","en":"Limit order","contentLocale":"zh-Hans","term":"限价单（Limit Order）","aka":["Limit order","限价委托","挂单"],"short":"限价单是指定价格买入或卖出的订单，只在市场价格达到或优于你设定的价格时才成交，可能部分成交或一直不成交。","body":[["限价买单只会以你设定的价格或更低价成交，限价卖单只会以你设定的价格或更高价成交。如果你的买价低于当前卖一价，订单会挂在",["订单簿","order-book"],"上等待，成为挂单（Maker），通常享受更低的手续费。"],"如果你的限价买单价格高于当前卖一价，它会立即以市场上更好的价格成交，这时属于吃单。很多人设置限价单是想等回调买入，或者在目标价位提前挂卖单止盈。",["限价单的风险是“不成交”：价格没到你的价位就掉头，你就错过了。限价单可以设置有效期（",["GTC","time-in-force"],"、IOC、FOK 等），也可以搭配“",["只做挂单","post-only-order"],"”（Post Only）选项，确保不会意外变成吃单。"]],"example":["假设 ",["ETH","ethereum"]," 现价 2,600 ",["USDT","usdt"],"，你想在回调时买入，于是挂一个 2,500 USDT 买 0.8 ETH 的限价单，冻结 2,000 USDT。两天后价格跌到 2,480 后反弹，你的订单在 2,500 全部成交，手续费按",["挂单费","maker-taker-fees"],"率 0.08% 计算约 1.6 USDT。如果价格最低只到 2,510 就涨回去，你的订单就一直挂着，2,000 USDT 也一直被冻结。"],"mistakes":["把限价买价设在当前价之上，以为会挂单，结果立即按市价成交。","忘了还有挂着的限价单，几周后行情变化时被意外成交。","对冷门币设置了很远的限价，以为一定会成交，实际一直没成交。"],"faq":[{"q":"限价单一定会成交吗？","a":"不一定。只有市场价格达到你的限价并且有足够对手单时才会成交，也可能只成交一部分。"},{"q":"限价单挂着会占用资金吗？","a":"会。挂单期间对应的资金或币会被冻结，撤单后才会释放。"}],"title":"什么是限价单？限价单的含义与用法","description":"限价单是什么？讲清限价买单和卖单如何成交、为什么挂单手续费更低、限价单不成交和资金冻结的问题，以及常见用法。","related":[["market-order","市价单（Market Order）","市价单是以当前市场上最优可得价格立即成交的订单，优点是成交快、几乎一定成交，缺点是无法控制成交价格。"],["post-only-order","只做挂单（Post-Only）","只做挂单（Post-Only）是一种限价单选项，保证订单只以挂单（Maker）身份进入订单簿，如果会立即成交为吃单就自动取消或调整。"],["time-in-force","订单有效期（GTC、IOC、FOK）","订单有效期（Time in Force）规定了一笔订单在未成交时保留多久以及如何处理未成交部分，常见选项有 GTC、IOC 和 FOK。"],["order-book","订单簿（Order Book）","订单簿是交易所实时列出某个交易对所有未成交买单和卖单的列表，按价格排列，显示每个价位挂了多少数量。"],["maker-taker-fees","挂单费与吃单费（Maker/Taker Fee）","挂单费与吃单费是交易所按订单角色收取的两档手续费：挂在订单簿上等待成交、提供流动性的一方付挂单费，立即与已有挂单成交的一方付吃单费。"]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"市价、限价、撤单，分别解决什么问题？"},"coin":null,"tool":null,"cta":true},"insurance-fund":{"slug":"insurance-fund","cat":"derivatives","en":"Insurance fund","contentLocale":"zh-Hans","term":"风险保障基金（Insurance Fund）","aka":["保险基金","风险准备金","insurance fund"],"short":"风险保障基金是合约交易所设立的资金池，用来弥补被强平仓位以差于破产价格成交时产生的穿仓损失，避免盈利方的收益受到影响。","body":[["每个仓位都有一个破产价格，也就是保证金刚好亏光的价格。",["强平","liquidation"],"引擎接管仓位后，如果能以比破产价格更好的价格平掉，剩下的保证金一般会进入保险基金；如果只能以更差的价格平掉，差额就由保险基金补上。"],["保险基金的规模在一定程度上反映",["交易所","centralized-exchange"],"应对极端行情的能力。很多大型交易所会公开各合约保险基金的余额和历史变化，部分还会分合约或分币种设立。基金耗尽时，就会启动",["自动减仓（ADL）","auto-deleveraging"],"。"],"保险基金不是用户的存款保险，也不保障交易所破产或被盗。它只在合约强平环节起作用，和交易所的储备证明、用户资产保护基金等是不同的概念，名字相似但用途不同。"],"example":["假设一笔 3 ",["BTC","bitcoin"]," 的多单被强平，破产价格是 59,000 ",["USDT","usdt"],"。行情平稳时，强平引擎在 59,200 卖出，每 BTC 比破产价好 200，共 600 USDT 进入保险基金。行情剧烈时，引擎只能在 58,700 卖出，每 BTC 差 300，共 900 USDT 的穿仓损失由保险基金补足，对手方的盈利不受影响。"],"mistakes":["以为保险基金会赔偿自己被强平的损失，其实它不补偿被强平的用户。","把合约保险基金当作交易所破产或被盗时的用户资产保障。","交易保险基金很小的小币合约时，忽视发生 ADL 的可能。"],"faq":[{"q":"保险基金的钱从哪里来？","a":"主要来自强平时以优于破产价格成交后剩余的保证金，部分交易所也会自行注资。"},{"q":"保险基金会赔我被强平的钱吗？","a":"不会。保险基金弥补的是穿仓造成的缺口，保护的是对手方的盈利，被强平的用户的保证金不在赔付范围内。"}],"title":"风险保障基金是什么？合约保险基金的作用","description":"解释合约交易所的风险保障基金（保险基金）资金从哪里来、如何弥补穿仓损失、何时会启动自动减仓，以及它不能保障什么。","related":[["auto-deleveraging","自动减仓（ADL）","自动减仓（ADL）是合约交易所在强平仓位无法以足够好的价格平掉、风险保障基金又不足以弥补亏损时，按排名强制减少对手方盈利仓位的风控机制。"],["liquidation","强平（Liquidation）","强平（俗称爆仓）是指杠杆或合约仓位的保证金因亏损低于维持保证金要求时，交易所系统自动强制平掉该仓位，以防亏损超过保证金。"],["proof-of-reserves","储备金证明（Proof of Reserves）","储备金证明（PoR）是交易所公开证明自己持有的用户资产储备至少等于用户存款总额的做法，通常结合默克尔树和链上地址来让用户自行核验。"],["mark-price","标记价格（Mark Price）","标记价格是交易所用来计算未实现盈亏和判断强平的参考价格，通常以多家现货交易所的指数价格为基础，比最新成交价更难被短时操纵。"]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"爆仓：谁按下了强制平仓按钮？"},"coin":null,"tool":"/liquidations","cta":false},"block-confirmations":{"slug":"block-confirmations","cat":"wallets-security","en":"Block confirmations","contentLocale":"zh-Hans","term":"区块确认数（Confirmations）","aka":["确认数","区块确认","Confirmations"],"short":"区块确认数是指一笔交易被打包进区块后，其后又新增了多少个区块，确认数越多，交易被回滚的可能性越小，交易所据此决定何时为你入账。","body":[["交易被第一次打包时算 1 个确认，之后每多出一个新区块，确认数加 1。新区块越多，想推翻这笔",["交易所","centralized-exchange"],"需的",["算力","hash-rate"],"或成本就越高，所以确认数代表了交易的“牢固程度”。"],["交易所对不同链设定了不同的入账和解锁要求。",["比特币","bitcoin"],"出块平均约 10 分钟，常见要求是 1 到几个确认；出块快的链可能要求几十甚至上百个确认，但实际耗时未必更长。具体数字以各交易所充币页面为准，同一条链在不同平台也可能不一样。"],"有些交易所会区分“入账确认数”和“解锁确认数”：达到前者后你能看到余额并交易，达到后者才可以提现。"],"example":["假设你向某交易所充值 2,000 ",["USDT","usdt"],"，选择的网络要求 12 个确认才入账，该链大约每 3 秒出一个块。12 乘以 3 秒等于 36 秒，所以理论上不到一分钟就能入账。若你看到",["区块浏览器","block-explorer"],"显示已有 5 个确认，就知道还需大约 7 个区块、约 21 秒，不必担心币丢了。"],"mistakes":["在区块浏览器看到“成功”就认为交易所应该立即入账，忽略了确认数要求。","把不同链的确认数直接对比，以为数字大就一定慢。","网络拥堵时反复提交同一笔提现，造成重复转账或手续费浪费。"],"faq":[{"q":"为什么我的充值卡在确认中？","a":"可能是链上拥堵、出块变慢，或者交易手续费设置过低迟迟未被打包。先用交易哈希查看当前确认数，再对照交易所要求的数量。"},{"q":"确认数达到了还没到账怎么办？","a":"检查是否选对网络、是否漏填 Memo，以及充值的币种该平台是否支持。确认无误后，带上交易哈希联系客服。"}],"title":"什么是区块确认数？为什么充币要等确认","description":"区块确认数是什么意思？了解确认数如何计算、交易所为什么要求一定数量的确认、到账时间怎么估算，以及充值卡住时如何排查。","related":[["transaction-hash","交易哈希（TxID）","交易哈希（TxID）是每笔链上交易独一无二的编号，由交易数据计算得出，用它可以在区块浏览器里查到这笔转账的状态、金额和确认数。"],["block-explorer","区块浏览器（Block explorer）","区块浏览器是一种可以按交易哈希、钱包地址或区块高度查询区块链上公开记录的网站或工具，例如以太坊的Etherscan和波场的Tronscan。"],["mempool","内存池（Mempool）","内存池是区块链节点用来暂存已广播但尚未被打包进区块的交易的等待区，交易在这里排队，矿工或验证者通常优先打包手续费更高的交易。"],["blockchain","区块链（Blockchain）","区块链是一种由众多节点共同维护、按时间顺序把交易打包成区块并用密码学串联起来的公开账本，写入后极难篡改。"]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"显示成功却没到账，该查哪里？"},"coin":null,"tool":null,"cta":false},"impermanent-loss":{"slug":"impermanent-loss","cat":"defi","en":"Impermanent loss","contentLocale":"zh-Hans","term":"无常损失（Impermanent Loss）","aka":["无常损失","非永久性损失","IL","Impermanent loss"],"short":"无常损失是指你在 AMM 流动性池中提供流动性时，因两种代币价格比例变化，导致取回资产的价值低于单纯持有这些代币所造成的差额。","body":[[["AMM","amm"]," 会随着价格变化自动调整池中两种代币的数量：某个币涨了，",["套利","arbitrage"],"者就会从池子里买走它，你的份额里这个币变少，另一个币变多。结果是涨的币你拿得少，跌的币你拿得多，相对单纯持有就产生了差距。"],"之所以叫“无常”，是因为如果价格回到你存入时的比例，这部分损失会消失；但如果你在价格偏离时取出，损失就变成实际亏损。价格变化越大，无常损失越大，与涨跌方向无关。",["手续费收入可以部分甚至完全抵消无常损失。",["稳定币","stablecoin"],"对稳定币的池子价格比例变化小，无常损失通常很低；波动大的币对则相反。集中",["流动性池","liquidity-pool"],"在价格超出区间时，损失会被放大。"]],"example":["假设 ",["ETH","ethereum"]," 价格为 2,000 ",["USDC","usdc"]," 时，你存入 1 ETH 和 2,000 USDC，共 4,000 USDC。之后 ETH 涨到 8,000 USDC，按恒定乘积公式，你的份额变为 0.5 ETH 和 4,000 USDC，价值 8,000 USDC。如果当初只是持有，价值是 8,000 加 2,000，即 10,000 USDC。两者相差 2,000 USDC，无常损失为 20%，还没算你赚到的手续费。"],"mistakes":["以为币价上涨时做 LP 一定比持币赚得多。","只算手续费收益，不和“单纯持有”做对比。","在价格大幅偏离时匆忙退出，把无常损失变成了实际亏损。"],"faq":[{"q":"无常损失能避免吗？","a":"无法完全避免，只能降低：选择价格相关性高的币对（如两种稳定币），或确保手续费收入足以覆盖预期的价格波动。"},{"q":"币价跌了也会有无常损失吗？","a":"会。无常损失只看价格比例变化幅度，不分涨跌，跌一半和涨一倍都会造成损失。"}],"title":"什么是无常损失？计算方法与举例","description":"无常损失是什么意思？通过具体数字计算讲清做 LP 时为什么会比单纯持币少赚、无常损失与涨跌方向的关系，以及降低它的方法。","related":[["liquidity-pool","流动性池（Liquidity Pool）","流动性池是锁在智能合约里的一对或多种代币储备，交易者直接与池子兑换，存入资金的流动性提供者按份额获得手续费收入，是 DEX 运作的基础。"],["amm","自动做市商（AMM）","自动做市商（AMM）是一种用流动性池和数学公式自动给代币定价的交易机制，不需要买卖双方挂单撮合，是 Uniswap 等去中心化交易所的核心。"],["yield-farming","流动性挖矿（Yield Farming）","流动性挖矿是指把加密资产存入 DeFi 协议提供流动性或借贷，以赚取手续费、利息以及协议额外发放的代币奖励的做法。"],["apr-vs-apy","APR 和 APY 的区别","APR 是不计复利的年化收益率，APY 是计入复利后的年化收益率；同一个利率下，复利频率越高，APY 就比 APR 高得越多。"]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"liquid-staking":{"slug":"liquid-staking","cat":"defi","en":"Liquid staking","contentLocale":"zh-Hans","term":"流动性质押（Liquid Staking）","aka":["流动性质押","LST","Liquid staking","质押凭证"],"short":"流动性质押是把代币交给质押协议进行质押，同时获得一个可交易的凭证代币（如 stETH），让你在赚取质押奖励的同时仍能使用这部分资产。","body":[["传统",["质押","staking"],"会把代币锁住，无法自由转让。流动性质押协议（例如 Lido）替你把 ",["ETH","ethereum"]," 质押到",["验证者","validator"],"，并发给你等量的凭证代币。质押奖励会体现在凭证数量增加或兑换比例上升上。"],["凭证代币可以在 ",["DEX","dex"]," 上交易，也能在",["借贷协议","defi-lending"],"中作抵押或参与其他 ",["DeFi","defi"]," 策略，资金利用率更高。很多交易所也推出了自己的质押凭证。"],"风险包括：协议合约风险、验证者被罚没、凭证在二级市场与原生币脱锚。市场恐慌或流动性不足时，凭证价格可能出现明显折价，如果你此时被迫卖出，就会承受损失。"],"example":"假设你把 10 ETH 存入流动性质押协议，获得约 10 枚凭证代币，年化质押收益约 3%，协议抽取 10% 作为费用，一年后约增加 0.27 ETH 等值。如果某天市场恐慌，凭证代币在 DEX 上的价格跌到 0.96 ETH，你此时卖出 10 枚只能换回约 9.6 ETH，比原本少了 0.4 ETH。","mistakes":["以为凭证代币永远等于 1 枚原生币，忽略了二级市场折价。","用凭证代币高杠杆循环借贷，脱锚时被清算。","不区分不同协议的凭证，风险和流动性差别很大。"],"faq":[{"q":"stETH 和 ETH 是一样的吗？","a":"不完全一样。stETH 代表在 Lido 质押的 ETH 及其奖励，正常情况下价格接近 ETH，但在市场压力下可能出现折价。"},{"q":"流动性质押和普通质押哪个好？","a":"流动性质押更灵活，可以继续在 DeFi 中使用，但多了合约风险和脱锚风险；普通质押结构更简单，但资金被锁定。"}],"title":"什么是流动性质押？stETH 等质押凭证的原理","description":"流动性质押是什么意思？了解 Lido 等协议如何发放 stETH 这类质押凭证、凭证如何累积奖励，以及脱锚和杠杆清算等风险。","related":[["staking","质押（Staking）","质押是把权益证明（PoS）区块链的代币锁定，用来支持网络验证并获得奖励的做法，你可以自己运行验证节点，也可以通过交易所或质押服务参与。"],["restaking","再质押（Restaking）","再质押是把已经质押的 ETH 或流动性质押凭证，再次用于为其他网络或服务提供安全保障，以换取额外奖励，同时承担额外罚没风险的做法。"],["wrapped-token","封装代币（Wrapped Token）","封装代币是把一种资产按 1:1 比例在另一条链或另一种标准下表示出来的代币，例如 WBTC 让比特币能在以太坊上使用，WETH 把 ETH 变成 ERC20 格式。"],["depeg","脱锚（Depeg）","脱锚是指稳定币或锚定类资产的市场价格明显偏离它承诺跟随的价值，例如本应等于1美元的稳定币跌到0.95美元或涨到1.03美元。"]],"lesson":null,"coin":{"slug":"lido-dao","name":"Lido DAO","symbol":"LDO"},"tool":null,"cta":false},"restaking":{"slug":"restaking","cat":"defi","en":"Restaking","contentLocale":"zh-Hans","term":"再质押（Restaking）","aka":["再质押","重质押","Restaking","LRT"],"short":"再质押是把已经质押的 ETH 或流动性质押凭证，再次用于为其他网络或服务提供安全保障，以换取额外奖励，同时承担额外罚没风险的做法。","body":[["以 EigenLayer 为代表，再质押协议允许",["质押","staking"],"者把同一份 ",["ETH","ethereum"]," 的经济担保“借给”其他服务，比如",["预言机","oracle"],"、数据可用性层或跨链系统。这些服务向再质押者支付奖励，作为借用以太坊安全性的报酬。"],["此外还出现了",["流动性","liquidity"],"再质押代币（LRT），它把再质押后的头寸再变成可交易的凭证，类似",["流动性质押","liquid-staking"],"的思路，但又叠加了一层。"],"收益增加的同时风险也在叠加：除了以太坊本身的罚没规则，你还要接受其他服务的罚没条件；多层合约意味着更多漏洞可能；LRT 的流动性和价格锚定也比原生 ETH 弱。"],"example":"假设你持有 10 ETH，通过流动性质押获得约 3% 的基础收益，再把凭证拿去再质押，额外获得约 2% 的奖励，总计约 5%，一年约 0.5 ETH。但如果其中一个服务因故障触发 5% 的罚没，你会损失 0.5 ETH，相当于把一整年的额外收益和基础收益一起抵掉。","mistakes":["只看叠加后的收益率，不了解罚没条件由哪些服务决定。","把再质押凭证当成和 ETH 等价的资产进行高杠杆操作。","为了积分或空投预期参与，却没计算锁定期和退出时间。"],"faq":[{"q":"再质押和质押有什么区别？","a":"质押是为某一条链的共识提供担保；再质押是把同一份质押资产再为其他服务提供担保，奖励更多，罚没风险也更多。"},{"q":"再质押安全吗？","a":"它比单纯质押多了合约、服务方罚没和流动性等多层风险，属于较复杂的 DeFi 产品，投入前应了解具体协议的规则。"}],"title":"什么是再质押（Restaking）？原理与风险","description":"再质押 Restaking 是什么？了解 EigenLayer 等协议如何让质押资产再次提供安全保障、LRT 凭证的作用，以及叠加罚没的风险。","related":[["liquid-staking","流动性质押（Liquid Staking）","流动性质押是把代币交给质押协议进行质押，同时获得一个可交易的凭证代币（如 stETH），让你在赚取质押奖励的同时仍能使用这部分资产。"],["staking","质押（Staking）","质押是把权益证明（PoS）区块链的代币锁定，用来支持网络验证并获得奖励的做法，你可以自己运行验证节点，也可以通过交易所或质押服务参与。"],["validator","验证者（Validator）","验证者是权益证明区块链上质押代币、负责提议和验证新区块的节点运营者，正常工作获得奖励，违规会被罚没质押。"],["smart-contract","智能合约（Smart Contract）","智能合约是部署在区块链上、满足预设条件就自动执行的程序代码，DeFi、NFT 和链上代币都依靠它运行。"]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"defi-lending":{"slug":"defi-lending","cat":"defi","en":"DeFi lending","contentLocale":"zh-Hans","term":"DeFi 借贷","aka":["去中心化借贷","链上借贷","DeFi lending","借贷协议"],"short":"DeFi 借贷是通过智能合约进行的超额抵押借贷，存款人把资产存入资金池赚利息，借款人先存入抵押品再借出其他资产，抵押不足时会被自动清算。","body":[["以 Aave、Compound 等协议为例，存款人把 ",["USDC","usdc"],"、",["ETH","ethereum"]," 等资产存入",["资金池","liquidity-pool"],"获得利息；借款人存入抵押品后，可以按一定比例借出别的资产。利率由资金池的使用率决定，借的人越多，利率越高。"],["为防止坏账，",["DeFi","defi"]," 借贷几乎都是超额抵押：例如存入价值 1,000 美元的 ETH，最多只能借出几百美元的",["稳定币","stablecoin"],"。协议通过",["预言机","oracle"],"获取价格，一旦抵押品价值下降到清算线，清算人就会以折扣价买走你的部分抵押品偿还债务，你还要付出清算罚金。"],"常见用途包括：不卖币获得流动资金、做多或做空、循环借贷放大收益。每个协议、每种资产的抵押率和清算阈值都不同，以协议页面为准。"],"example":"假设你存入 2 ETH 作为抵押，ETH 价格为 3,000 USDC，抵押品价值 6,000 USDC，清算阈值为 80%。你借出 3,000 USDC，健康因子为 6,000 乘以 80% 再除以 3,000，等于 1.6。当 ETH 跌到 1,875 USDC 时，抵押品价值 3,750 USDC，乘以 80% 正好等于 3,000，健康因子降到 1，开始触发清算。","mistakes":["借到接近上限，币价稍微波动就被清算。","不关注浮动利率，借款成本上升后仍长期不还。","抵押品和借出资产都是高波动币，双向风险叠加。"],"faq":[{"q":"DeFi 借贷为什么要超额抵押？","a":"链上借贷没有信用评估和催收手段，只能靠抵押品价值高于借款来保证偿还，抵押不足时由清算机制自动处理。"},{"q":"健康因子是什么意思？","a":"健康因子衡量你的抵押是否充足，一般大于 1 表示安全，越接近 1 越危险，低于 1 就会被清算。"}],"title":"什么是 DeFi 借贷？超额抵押与清算机制","description":"DeFi 借贷是什么？了解 Aave 等链上借贷协议的存款利息、超额抵押、健康因子与清算线，并通过计算例子看清被清算的价格。","related":[["defi","DeFi（去中心化金融）","DeFi（去中心化金融）是指运行在区块链智能合约上的金融服务，比如交易、借贷、质押和收益聚合，用户用自己的钱包直接参与，无需银行或交易所作为中介。"],["liquidation","强平（Liquidation）","强平（俗称爆仓）是指杠杆或合约仓位的保证金因亏损低于维持保证金要求时，交易所系统自动强制平掉该仓位，以防亏损超过保证金。"],["oracle","预言机（Oracle）","预言机是把链下数据（如币价、汇率、体育比分）传送到区块链上供智能合约使用的服务，DeFi 借贷、衍生品和稳定币都依赖它获取价格。"],["crypto-backed-stablecoin","加密资产抵押型稳定币（Crypto-backed stablecoin）","加密资产抵押型稳定币是用户把ETH等加密资产超额抵押进智能合约后铸造出来的稳定币，DAI是最典型的例子，抵押品不足时仓位会被清算。"],["flash-loan","闪电贷（Flash Loan）","闪电贷是一种无需抵押的链上借款，借款和还款必须在同一笔交易内完成，如果交易结束时没有连本带息还清，整笔交易就会被撤销，就像没发生过一样。"]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"cbdc":{"slug":"cbdc","cat":"stablecoins","en":"CBDC (central bank digital currency)","contentLocale":"zh-Hans","term":"央行数字货币（CBDC）","aka":["CBDC","数字法币","法定数字货币"],"short":"央行数字货币（CBDC）是由一个国家或地区的中央银行发行的数字形式法定货币，与现金一样是央行的直接负债，例如中国的数字人民币（e-CNY）。","body":[["CBDC和你银行卡里的余额不同：银行存款是商业银行欠你的钱，而CBDC直接是央行的负债，信用等级相当于现金。它和USDT、USDC也不同，",["稳定币","stablecoin"],"由私人公司发行，靠储备资产支撑；CBDC则由国家发行，具有法偿性。"],["CBDC通常分为零售型和批发型。零售型面向个人和商户，用于日常支付，比如数字人民币钱包；批发型主要在银行等金融机构之间做大额结算。许多CBDC由央行集中运营，不一定使用公链，也不会像",["比特币","bitcoin"],"那样任何人都能查看全部账本。"],"对加密用户来说，CBDC并不是一种可以投资增值的加密资产，它的价值就是1单位法币。各国推进的进度、隐私设计和可编程程度差别很大，有的已经试点，有的仍在研究，有的明确暂不推出。"],"example":["假设你的数字人民币钱包里有500元，你在便利店付了30元，余额变为470元，这470元是央行的负债，和你钱包里的纸币性质相同。而如果你在",["交易所","centralized-exchange"],"持有500 ",["USDT","usdt"],"，它是Tether公司的负债，价值依赖Tether的储备；你若把500 USDT换成ETH，价格会随市场波动，而470元数字人民币始终等于470元人民币。"],"mistakes":["把CBDC当成一种会涨跌的加密货币，以为可以炒作获利。","以为CBDC就是稳定币，忽略了发行主体和法律地位的区别。","认为所有CBDC都运行在公开区块链上，可以像比特币一样匿名或公开查询。"],"faq":[{"q":"数字人民币是加密货币吗？","a":"不是。数字人民币是中国人民银行发行的法定货币数字形式，价值与人民币一比一，不存在价格波动，也不属于去中心化加密资产。"},{"q":"CBDC会取代稳定币吗？","a":"两者定位不同。CBDC由央行发行、主要服务本国支付体系，稳定币由私人机构发行、广泛用于加密交易和跨境转账，目前更多是并存关系。"}],"title":"什么是CBDC？央行数字货币与稳定币的区别","description":"CBDC央行数字货币是什么？与银行存款、USDT等稳定币有何不同？了解零售型与批发型CBDC，以及数字人民币的定位。","related":[["stablecoin","稳定币（Stablecoin）","稳定币是一种设计为与美元等法币或资产保持稳定兑换比例的加密货币，最常见的是 1 枚兑 1 美元的 USDT 和 USDC，是加密交易中的主要计价和结算工具。"],["fiat-on-ramp","法币入金通道（Fiat on-ramp）","法币入金通道是把美元、欧元、人民币等法定货币换成加密资产的渠道，例如银行转账、银行卡快捷买币、第三方支付和P2P（C2C）交易。"],["kyc","KYC（了解你的客户）","KYC是“了解你的客户”（Know Your Customer）的缩写，指交易所等金融服务机构在开户或提高额度时核实用户真实身份的流程，通常需要证件和人脸识别。"],["blockchain","区块链（Blockchain）","区块链是一种由众多节点共同维护、按时间顺序把交易打包成区块并用密码学串联起来的公开账本，写入后极难篡改。"]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"USDT是美元吗？为什么买币常见它？"},"coin":null,"tool":null,"cta":false},"node":{"slug":"node","cat":"onchain","en":"Node","contentLocale":"zh-Hans","term":"节点（Node）","aka":["区块链节点","全节点","Node"],"short":"节点是运行区块链客户端软件、保存账本数据并按共识规则验证和转发交易与区块的计算机，全节点会独立校验每一个区块是否合法。","body":[[["区块链","blockchain"],"没有中央服务器，而是由分布在全球的节点共同维护。全节点保存完整（或经过裁剪）的区块数据，独立检查每笔交易的签名、余额和每个区块是否符合规则；轻节点只下载区块头，依赖全节点提供数据，适合手机钱包。"],["节点不等于矿工或",["验证者","validator"],"。在",["比特币","bitcoin"],"网络里，矿工负责出块，但任何人都可以运行全节点来验证矿工的工作；在",["以太坊","ethereum"],"等",["权益证明","proof-of-stake"],"链上，验证者节点需要",["质押","staking"],"ETH才能参与出块和投票。普通全节点不赚取奖励，它的价值在于让你不必信任别人就能确认链上数据。"],"你日常使用的钱包和交易所，背后都连接着节点。钱包显示的余额、发出的交易，都要经过某个节点。自己运行节点需要一定的硬盘空间、带宽和维护成本，比特币全节点的数据量已达数百GB，不同链的硬件要求差别很大。"],"example":"假设一位矿工挖出新区块，并在区块里给自己写了4 BTC的奖励。按当前规则，区块补贴只有3.125 BTC，再加上这个区块里交易手续费合计0.2 BTC，最多只能领取3.325 BTC。你运行的全节点在验证时发现多出0.675 BTC，会直接拒绝这个区块，不再转发给其他节点。只要大部分节点都这样做，这个违规区块就无法进入主链。","mistakes":["以为运行一个比特币全节点就能像挖矿一样获得收益。","把节点、矿工和验证者混为一谈，不清楚各自的职责。","在钱包里随意填写来历不明的第三方节点地址，可能被提供错误数据或泄露隐私。"],"faq":[{"q":"普通人有必要运行全节点吗？","a":"不是必须的，但运行全节点可以让你自行验证交易和余额，不依赖第三方，也能提升隐私和网络的去中心化程度。"},{"q":"节点和验证者有什么区别？","a":"节点泛指运行区块链客户端的计算机；验证者是权益证明链上质押了代币、负责出块和投票的特殊节点，可以获得奖励，也可能因违规被罚没。"}],"title":"什么是区块链节点？全节点、轻节点与验证者","description":"区块链节点是什么？了解全节点、轻节点和验证者的区别，节点如何验证交易和区块，以及普通人运行全节点的意义。","related":[["blockchain","区块链（Blockchain）","区块链是一种由众多节点共同维护、按时间顺序把交易打包成区块并用密码学串联起来的公开账本，写入后极难篡改。"],["validator","验证者（Validator）","验证者是权益证明区块链上质押代币、负责提议和验证新区块的节点运营者，正常工作获得奖励，违规会被罚没质押。"],["mining","挖矿（Crypto Mining）","挖矿是在工作量证明区块链上用计算设备竞争打包区块、维护网络安全并获得新币奖励和手续费的过程。"],["mempool","内存池（Mempool）","内存池是区块链节点用来暂存已广播但尚未被打包进区块的交易的等待区，交易在这里排队，矿工或验证者通常优先打包手续费更高的交易。"]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"aml":{"slug":"aml","cat":"regulation","en":"AML (anti-money laundering)","contentLocale":"zh-Hans","term":"AML（反洗钱）","aka":["反洗钱","AML合规","反洗钱审查"],"short":"AML是“反洗钱”（Anti-Money Laundering）的缩写，指金融机构和交易所为识别、阻止非法资金进入正规体系而建立的一整套监控、审查和报告制度。","body":[["AML比KYC范围更广：KYC负责确认“你是谁”，AML则持续监控“你的钱从哪里来、到哪里去”。",["交易所","centralized-exchange"],"会用链上风控工具给充值来源打分，检查资金是否与诈骗、黑客、暗网市场或受制裁地址有关联，并在交易模式异常时触发人工审查。"],"当风控命中时，平台可能要求你提供资金来源说明、交易截图或银行流水，在审查期间临时冻结部分资产或限制提现。情节严重的，平台会依法向监管机构报告。这些规则来自各国的反洗钱法律以及FATF的国际标准，不同地区的执行力度不同。",["对普通用户来说，最常见的AML风险来自P2P（",["C2C","p2p-trading"],"）交易：你收到的法币或币如果来自诈骗受害者或涉案账户，你的银行卡或交易所账户都可能被牵连。选择信誉好的商家、保留交易记录，是保护自己的有效方式。"]],"example":["假设你在P2P市场向陌生商家买入5,000 USDT并提到另一个交易所，入账后账户被风控暂停提现。原因是",["链上分析","on-chain-analysis"],"显示，这5,000 USDT在三次转手前来自一个被标记的诈骗地址。平台要求你提供P2P订单截图、付款凭证和聊天记录。你提交后审核通过，账户恢复；如果你无法说明来源，这笔资金可能一直被冻结。"],"mistakes":["帮陌生人“代收代付”或出借银行卡、交易所账户，卷入洗钱链条。","账户被风控后删掉聊天记录和付款凭证，无法证明资金来源。","频繁拆分大额转账想规避审查，反而更容易触发风控。"],"faq":[{"q":"AML和KYC有什么区别？","a":"KYC是开户时核实身份，AML是更广的反洗钱体系，包括持续监控交易、审查资金来源和向监管报告可疑活动。"},{"q":"账户因AML被冻结怎么办？","a":"通过官方客服渠道配合审查，按要求提交订单记录、付款凭证和资金来源说明，不要相信声称可以“花钱解冻”的第三方。"}],"title":"什么是AML反洗钱？交易所风控与冻结原因","description":"AML反洗钱是什么意思？了解交易所如何监控资金来源、为什么账户会被风控冻结，以及P2P交易中如何避免被牵连。","related":[["kyc","KYC（了解你的客户）","KYC是“了解你的客户”（Know Your Customer）的缩写，指交易所等金融服务机构在开户或提高额度时核实用户真实身份的流程，通常需要证件和人脸识别。"],["travel-rule","旅行规则（Travel Rule）","旅行规则是FATF第16条建议对虚拟资产服务商的要求：在转账时收集并传递汇款方和收款方的身份信息，让资金和信息一起“旅行”。"],["vasp","虚拟资产服务提供商（VASP）","VASP是“虚拟资产服务提供商”的缩写，指为他人提供加密资产兑换、转账、托管或发行相关服务的企业，例如中心化交易所和托管钱包服务商。"],["p2p-trading","P2P交易（C2C交易）","P2P交易（币圈常称C2C）是指用户之间在交易所提供的撮合平台上直接买卖加密资产，买方通过银行转账等方式付款给卖方，平台托管卖方的币作为担保。"]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"KYC怎么做？证件应该交给谁？"},"coin":null,"tool":null,"cta":false},"tokenized-gold":{"slug":"tokenized-gold","cat":"tokenized-assets","en":"Tokenized gold","contentLocale":"zh-Hans","term":"代币化黄金（Tokenized gold）","aka":["黄金代币","链上黄金","PAXG","XAUT"],"short":"代币化黄金是由发行方在金库中托管实物黄金、并按固定比例在区块链上发行的代币，例如1枚PAXG或XAUT对应1金衡盎司黄金，价格跟随金价变动。","body":[["Paxos发行的PAXG和Tether发行的XAUT是两种常见的黄金代币，每枚代币对应1金衡盎司存放在专业金库中的金条。你可以在",["交易所","centralized-exchange"],"用USDT买卖，按小数单位持有，也可以提到自己的钱包，在链上全天候转账。"],"相比购买实物黄金，代币化黄金省去了保管、运输和鉴定的麻烦，买入门槛也低；相比黄金ETF，它可以在加密交易所全天候交易，并能在部分DeFi协议中作为抵押品。",["需要注意的是，你的权益依赖发行方的托管和审计是否可靠，以及代币能否按规则兑换成实物或现金。实物赎回通常有最低数量和费用要求。黄金本身也会波动，它是一种价格跟随金价的资产，不是",["稳定币","stablecoin"],"。"]],"example":["假设金价为每盎司2,500美元，你用500 USDT买入0.2枚PAXG，对应0.2盎司黄金。之后金价上涨4%到2,600美元，你的0.2枚代币价值约520 ",["USDT","usdt"],"，盈利约20 USDT。如果金价下跌4%到2,400美元，持仓价值约480 USDT，亏损约20 USDT。若把0.2枚提到自己的钱包，还要扣除交易所的",["提币手续费","withdrawal-fee"],"，以及",["以太坊","ethereum"],"网络的Gas成本。"],"mistakes":["把黄金代币当成稳定币，以为价格不会波动。","不了解发行方的审计和赎回规则，就认为随时能换成实物金条。","在交易对流动性很差的平台上大额买卖，承担过高的价差。"],"faq":[{"q":"1枚PAXG等于多少黄金？","a":"每枚PAXG对应1金衡盎司由Paxos托管在金库中的实物黄金，XAUT同样以1金衡盎司为单位。"},{"q":"代币化黄金和黄金ETF有什么区别？","a":"黄金ETF在证券市场交易，需要证券账户；代币化黄金在区块链和加密交易所上交易，可全天候转账，但依赖发行方的托管和赎回安排。"}],"title":"什么是代币化黄金？PAXG与XAUT原理解析","description":"代币化黄金是什么？了解PAXG、XAUT如何以实物黄金1:1托管发行、与实物金条和黄金ETF的区别，以及托管和赎回风险。","related":[["real-world-assets","现实世界资产（RWA）","现实世界资产（RWA）是指被代币化后在区块链上发行和流通的链下资产，例如国债、货币市场基金、私人信贷、房地产、黄金和股票等。"],["stablecoin","稳定币（Stablecoin）","稳定币是一种设计为与美元等法币或资产保持稳定兑换比例的加密货币，最常见的是 1 枚兑 1 美元的 USDT 和 USDC，是加密交易中的主要计价和结算工具。"],["custodial-wallet","托管钱包（Custodial Wallet）","托管钱包是由交易所或其他第三方代为保管私钥的钱包，你通过账户密码登录使用，资产实际由平台控制，便捷但要承担平台风险。"],["tokenized-stocks","代币化股票（Tokenized stocks）","代币化股票是把上市公司股票的价格和经济权益映射到区块链代币上的产品，通常由发行方托管真实股票并按1:1发行代币，可在交易所或链上交易。"]],"lesson":null,"coin":{"slug":"pax-gold","name":"PAX Gold","symbol":"PAXG"},"tool":"/topics/tokenized-assets","cta":false}});
